awb=openpyxl.load_workbook('/mnt/hhq/data/answer_files/1_598-14_answer.xlsx', data_only=False)
aws=awb['Monthly Trans']
def formulas(w):
    res=[]
    for row in w.iter_rows():
        for cell in row:
            v=cell.value
            if cell.data_type=='f':
                res.append((cell.coordinate, v))
            elif isinstance(v, ArrayFormula):
                res.append((cell.coordinate, 'ARR:'+v.text))
    return res
ff=formulas(ws)
af=formulas(aws)
for i,(a,b) in enumerate(zip(ff,af)):
    if a[0]!=b[0] or (a[1]!=b[1]):
        print('diff', i, a, b)
