import openpyxl
from openpyxl.worksheet.formula import ArrayFormula

# Compare filled2 vs answer for all cells (values + styles) across sheet
wb=openpyxl.load_workbook('1_598-14_answer_template_7348_input_filled2.xlsx', data_only=False)
ws=wb['Monthly Trans']
awb=openpyxl.load_workbook('/mnt/hhq/data/answer_files/1_598-14_answer.xlsx', data_only=False)
aws=awb['Monthly Trans']

def norm(v):
    if isinstance(v, ArrayFormula):
        return ('ARR', v.text, v.ref)
    if hasattr(v, 'text'):
        return ('ARR', v.text, getattr(v,'ref',None))
    return v

diffs=[]
maxr=max(ws.max_row, aws.max_row)
maxc=max(ws.max_column, aws.max_column)
for r in range(1, maxr+1):
    for c in range(1, maxc+1):
        a=ws.cell(row=r,column=c)
        b=aws.cell(row=r,column=c)
        va, vb = norm(a.value), norm(b.value)
        if va != vb:
            diffs.append((a.coordinate, va, vb))
        if a.style_id != b.style_id:
            diffs.append((a.coordinate+' style', a.style_id, b.style_id))
print('total diffs', len(diffs))
for d in diffs[:100]:
    print(d)
